 let inspectionSelectedId=null,inspectionStartNew=false;
 const inspectionPhotos=new Map(),inspectionSteps=new Map(),inspectionTypes={delivery:'Entrega do carro',periodic:'Vistoria de rotina',return:'Devolução do carro'},inspectionStatuses={draft:'Rascunho',submitted:'Aguardando conferência',changes_requested:'Correção solicitada',approved:'Aprovada no exemplo'};
 function inspectionProgress(step,title,help){return `<header class="inspection-step-heading"><p class="inspection-step-count">Passo ${step} de 4</p><div class="inspection-progress" role="progressbar" aria-label="Etapas da vistoria" aria-valuemin="1" aria-valuemax="4" aria-valuenow="${step}">${[1,2,3,4].map(n=>`<span class="${n<=step?'done':''}"></span>`).join('')}</div><h3 tabindex="-1" data-inspection-focus>${title}</h3><p>${help}</p></header>`;}
 function inspectionFocusStep(){const heading=root.querySelector('.inspection-driver [data-inspection-focus]');if(!heading)return;heading.focus({preventScroll:true});(heading.closest('.inspection-step-heading,.inspection-result')||heading).scrollIntoView({block:'start',behavior:'smooth'});}
 function inspectionVehicleLabel(vehicleId){const v=M.vehicles(ops).find(v=>v.id===vehicleId);return v?esc(v.model+' · '+v.plate):esc(vehicleId);}
 function inspectionCreate(){const vehicle=driverVehicle();return `<form id="inspection-create-form" class="inspection-wizard">${inspectionProgress(1,'Vamos começar pelo carro','Olhe o painel do carro para preencher estas informações.')}${vehicle?`<p class="inspection-car-name">${inspectionVehicleLabel(vehicle.id)}</p>${select('type','Qual vistoria você vai fazer?',driverProfile().stage==='active'?'periodic':'delivery',Object.entries(inspectionTypes))}<div class="inspection-start-fields">${input('km','Quantos km aparecem no painel?',vehicle.km,'type="number" inputmode="numeric" min="'+vehicle.km+'" step="1" required')}${input('chargePct','Qual a carga da bateria? (%)',50,'type="number" inputmode="numeric" min="0" max="100" step="1" required')}<p class="inspection-field-help">Bateria cheia = 100%. Veja o número no painel.</p></div><div class="inspection-step-actions"><button type="submit" class="btn primary">Continuar para os itens →</button></div>`:'<p class="notice amber">O carro ainda não foi definido. Peça ajuda à RODAVOLT para começar.</p>'}<p class="inspection-demo-note">Vistoria de teste. Nenhuma foto será enviada neste protótipo.</p></form>`;}
 function driverInspection(){const d=driverProfile(),records=I.forDriver(ops,d.id),selected=inspectionStartNew?null:(records.find(r=>r.id===inspectionSelectedId)||records.find(r=>['draft','changes_requested'].includes(r.status)));if(selected)inspectionSelectedId=selected.id;return `<div class="inspection-driver">${selected?inspectionEditor(selected):inspectionCreate()}${records.length?`<details class="inspection-history"><summary>Vistorias anteriores (${records.length})</summary>${records.map(r=>`<div class="inspection-history-record"><strong>${esc(inspectionTypes[r.type])}</strong><span>${esc(inspectionStatuses[r.status])}</span><small>${inspectionVehicleLabel(r.vehicleId)} · ${num(r.km)} km</small>${btn(['draft','changes_requested'].includes(r.status)?'Continuar esta vistoria':'Ver esta vistoria','inspection-select','',`data-id="${r.id}"`)}</div>`).join('')}</details>`:''}</div>`;}
 function inspectionImage(record,slot){const e=record.evidence.find(e=>e.slot===slot),url=inspectionPhotos.get(record.id+':'+slot);if(e?.source==='private')return serverSession?`<img src="/api/files/${esc(e.fileId)}" alt="Foto privada: ${esc(I.slots.find(([k])=>k===slot)[1])}"><a href="/api/files/${esc(e.fileId)}" target="_blank" rel="noopener">Abrir foto privada</a><small>Arquivo protegido pelo acesso individual</small>`:'<div class="evidence-empty">Foto privada<small>Abra pelo acesso individual para conferir.</small></div>';if(url)return `<img src="${url}" alt="Foto temporária da ${esc(I.slots.find(([k])=>k===slot)[1])}"><small>Foto apenas nesta sessão</small>`;if(e?.source==='illustrative')return `<div class="evidence-sample"><svg viewBox="0 0 180 80" aria-hidden="true"><path d="M20 51L39 45L54 25H119L137 44L158 51V65H20Z" fill="#abc6b5" stroke="#477861" stroke-width="2"/><path d="M60 30H112L124 44H49Z" fill="#e8f1ed"/><circle cx="49" cy="64" r="12" fill="#4a5e50"/><circle cx="130" cy="64" r="12" fill="#4a5e50"/></svg><small>ILUSTRAÇÃO · FOTO DE EXEMPLO</small></div>`;return `<div class="evidence-empty">${e?'Escolha esta foto novamente':'Ainda falta esta foto'}<small>${e?'A foto anterior não fica salva ao recarregar.':'Use a câmera ou uma foto do celular.'}</small></div>`;}
 function inspectionChecklist(r){const labels={tires:'Pneus, rodas e estepe',brakes:'Freios e luzes de aviso no painel',lights:'Faróis, lanternas e setas',body:'Lataria, para-choques e vidros',interior:'Bancos, limpeza e acessórios',charging:'Porta de recarga, cabo e alertas da bateria',kit:'Produtos da lojinha',equipment:'Chaves e itens de segurança'};return `<div class="inspection-checklist">${I.items.map(([key])=>`<fieldset class="inspection-check-item"><legend>${labels[key]}</legend><div class="inspection-check-options">${[['ok','Tudo certo'],['damage','Tem problema'],['na','Não se aplica']].map(([value,label])=>`<label><input type="radio" name="check-${key}" value="${value}" ${r.items[key]===value?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`).join('')}</div><label class="field inspection-note">Encontrou algum problema? Conte aqui.<textarea name="note" rows="3" maxlength="1500" placeholder="Exemplo: risco na porta do lado direito.">${esc(r.note)}</textarea></label>`;}
 function inspectionPhotoFields(r){return `<div class="inspection-photo-grid">${I.slots.map(([key,label],index)=>`<label class="evidence-slot inspection-photo-slot"><strong>${index+1}. ${label}</strong>${inspectionImage(r,key)}<span class="inspection-photo-prompt">${r.evidence.some(e=>e.slot===key)?'Escolher outra foto':'Tirar ou escolher foto'}</span><input type="file" accept="image/*" capture="environment" data-inspection-photo="${key}" data-inspection-id="${r.id}" aria-label="Foto: ${label}"></label>`).join('')}</div><p class="inspection-demo-note">As fotos ficam apenas nesta sessão. Ao recarregar, escolha de novo. O envio privado está disponível pelo acesso individual. Aqui as fotos são temporárias ou de exemplo.</p><details class="inspection-sample-help"><summary>Estou testando o aplicativo</summary><p>Você pode preencher as cinco vistas com ilustrações. Elas serão marcadas como exemplos.</p>${btn('Usar fotos de exemplo','inspection-examples','',`data-id="${r.id}"`)}</details>`;}
 function inspectionConfirm(r){const problems=I.items.filter(([key])=>r.items[key]==='damage');return `<div class="inspection-review-card">${row('Carro',inspectionVehicleLabel(r.vehicleId))}${row('Tipo',esc(inspectionTypes[r.type]))}${row('Km no painel',num(r.km)+' km')}${row('Carga da bateria',Number.isFinite(r.chargePct)?num(r.chargePct)+'%':'Não informada · registro anterior')}${row('Itens do carro',problems.length?problems.length+' com problema':'Conferidos')}${row('Fotos',r.evidence.length+' de 5 vistas')}${problems.length?`<p><strong>Problemas informados:</strong> ${problems.map(([,label])=>esc(label)).join(', ')}.</p>`:''}${r.note?`<p><strong>Seu comentário:</strong> ${esc(r.note)}</p>`:''}</div><p class="notice">Ao enviar, a RODAVOLT vai conferir sua vistoria. O envio sozinho não libera o carro.</p>`;}
 function inspectionEditor(r){if(!['draft','changes_requested'].includes(r.status)){const sent=r.status==='submitted';return `<section class="inspection-result"><span class="inspection-result-mark" aria-hidden="true">✓</span><h3 tabindex="-1" data-inspection-focus>${sent?'Vistoria enviada':r.status==='approved'?'Vistoria conferida':'Sua vistoria'}</h3><p>${sent?'Vamos conferir os itens e as fotos de exemplo. Você pode acompanhar a resposta por aqui.':esc(inspectionStatuses[r.status])}</p>${r.review?`<p class="notice">${esc(r.review.note)}</p>`:''}<button type="button" class="btn primary" data-driver-page="home">Voltar ao início</button><details class="inspection-sent-details"><summary>Ver o que foi informado</summary>${inspectionRead(r,false)}</details>${btn('Fazer outra vistoria','inspection-new')}</section>`;}const step=inspectionSteps.get(r.id)||1,titles={1:['Vamos conferir o painel','Confira os números antes de continuar.'],2:['Como está o carro?','Confira cada item e marque uma resposta.'],3:['Agora, as fotos','São cinco fotos. Faça uma de cada vez, com o carro parado.'],4:['Está tudo certo?','Confira o resumo. Se precisar corrigir, toque em Voltar.']};return `<form id="inspection-work-form" class="inspection-wizard" data-inspection-id="${r.id}" data-inspection-step="${step}">${inspectionProgress(step,...titles[step])}${r.review?`<p class="notice amber inspection-review-note"><strong>A RODAVOLT pediu uma correção:</strong> ${esc(r.review.note)}</p>`:''}${step===1?`<p class="inspection-car-name">${inspectionVehicleLabel(r.vehicleId)}</p><p class="inspection-field-help">${esc(inspectionTypes[r.type])}</p><div class="inspection-start-fields">${input('km','Quantos km aparecem no painel?',r.km,'type="number" inputmode="numeric" min="0" step="1" required')}${input('chargePct','Qual a carga da bateria? (%)',r.chargePct,'type="number" inputmode="numeric" min="0" max="100" step="1" required')}<p class="inspection-field-help">Bateria cheia = 100%. Veja o número no painel.</p></div>`:step===2?inspectionChecklist(r):step===3?inspectionPhotoFields(r):inspectionConfirm(r)}<div class="inspection-step-actions">${step>1?btn('← Voltar','inspection-back'):''}${btn(step===4?'Enviar vistoria':'Continuar →',step===4?'inspection-send':'inspection-next','primary',`data-id="${r.id}"`)}</div><button type="submit" class="btn inspection-save">Salvar para continuar depois</button><p class="inspection-save-note">O rascunho fica neste navegador. As fotos não ficam salvas.</p></form>`;}
 function inspectionRead(r,admin=true){return row('Vistoria',r.id+' · '+inspectionTypes[r.type])+row('Motorista e veículo',esc(M.driver(ops,r.driverId).name)+' · '+r.vehicleId)+row('Situação',tag(inspectionStatuses[r.status],r.status==='approved'?'green':'amber'))+row('Hodômetro / carga',num(r.km)+' km · '+(Number.isFinite(r.chargePct)?num(r.chargePct)+'%':'carga não informada · registro anterior'))+table(['Item','Registro'],I.items.map(([key,label])=>`<tr><td>${label}</td><td>${tag({ok:'OK',damage:'Avaria / atenção',na:'Não aplicável'}[r.items[key]]||'Pendente',r.items[key]==='damage'?'amber':'')}</td></tr>`).join(''))+`<p class="caption gap">Observações: ${esc(r.note||'Nenhuma observação registrada.')}</p><div class="evidence-grid gap">${I.slots.map(([key,label])=>`<div class="evidence-slot"><strong>${label}</strong>${inspectionImage(r,key)}</div>`).join('')}</div><p class="caption">${r.evidence.some(e=>e.source==='private')?'Fotos privadas no serviço local. A conferência humana não é assinatura eletrônica.':'Evidências ilustrativas/temporárias, sem validade de arquivo assinado.'} ${r.submittedAt?'Envio registrado em '+esc(new Date(r.submittedAt).toLocaleString('pt-BR'))+'.':''}</p>`+(r.review?`<div class="notice gap">Conferência: ${esc(r.review.note)}</div>`:'')+(admin&&r.status==='submitted'?`<form id="inspection-review-form" class="gap"><input type="hidden" name="entityId" value="${r.id}">${select('action','Decisão da conferência','changes',[['changes','Devolver para correção'],['approve','Aprovar vistoria no exemplo']])}<label class="field gap">Parecer e orientação<textarea name="note" required rows="3" maxlength="1000"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Registrar conferência</button></div><p class="caption">${r.type==='return'?'A devolução registra as avarias encontradas. Problemas de segurança exigem manutenção antes de o carro voltar a disponível.':'Itens de segurança com avaria impedem a aprovação para entrega ou rotina.'} Conferir vistoria não assina contrato nem inicia aluguel.</p></form>`:'');}
 function inspectionAdmin(){const records=I.ensure(ops).records;return `<div class="notice">Checklists enviados pelo app do motorista. Revise itens, avarias e evidências antes de liberar a entrega.</div>${records.length?records.slice().reverse().map(r=>row(r.id+' · '+inspectionTypes[r.type],tag(inspectionStatuses[r.status],r.status==='approved'?'green':'amber'),esc(M.driver(ops,r.driverId).name)+' · '+r.vehicleId)+btn('Abrir conferência','inspection-review','',`data-id="${r.id}"`)).join(''):'<p class="caption gap">Ainda sem vistoria nesta versão. Abra App do motorista → Vistoria para iniciar.</p>'}`;}
 function inspectionSaveForm(){const form=root.querySelector('#inspection-work-form');if(!form)return null;const f=new FormData(form),r=I.lookup(ops,form.dataset.inspectionId),nextItems={...r.items};for(const [key]of I.items){if(form.querySelector(`[name="check-${key}"]`))nextItems[key]=String(f.get('check-'+key)||'');}return I.save(ops,r.id,{km:f.has('km')&&String(f.get('km')).trim()!==''?Number(f.get('km')):f.has('km')?NaN:r.km,chargePct:f.has('chargePct')&&String(f.get('chargePct')).trim()!==''?Number(f.get('chargePct')):f.has('chargePct')?NaN:r.chargePct,note:f.has('note')?String(f.get('note')):r.note,items:nextItems,evidence:r.evidence});}
 function inspectionError(message){const form=root.querySelector('#inspection-work-form,#inspection-create-form');if(!form){reportError(message);return;}let node=form.querySelector('.inspection-form-error');if(!node){node=document.createElement('p');node.className='notice red inspection-form-error';node.setAttribute('role','alert');node.setAttribute('tabindex','-1');form.querySelector('.inspection-step-heading')?.after(node);}node.textContent=message;node.focus();node.scrollIntoView({block:'nearest',behavior:'smooth'});}
 function inspectionCheckStep(r,step){if(step===2){if(I.items.some(([key])=>!r.items[key]))throw new RangeError('Falta responder algum item. Escolha uma resposta para cada parte do carro.');if(Object.values(r.items).includes('damage')&&!r.note.trim())throw new RangeError('Conte no campo de comentário qual problema você encontrou.');}if(step===3||step===4){if(r.evidence.length!==I.slots.length)throw new RangeError('Ainda faltam fotos. Inclua as cinco vistas do carro.');if(r.evidence.some(ev=>ev.source==='temporary'&&!inspectionPhotos.has(r.id+':'+ev.slot)))throw new RangeError('As fotos anteriores não ficaram salvas. Volte ao passo das fotos e escolha novamente.');}}
 function inspectionAction(action,e){if(!action.startsWith('inspection-'))return false;if(action==='inspection-admin'){open('Central de vistorias',inspectionAdmin());return true;}if(action==='inspection-review'){open('Conferência · '+e.dataset.id,inspectionRead(I.lookup(ops,e.dataset.id)));return true;}try{if(action==='inspection-select'){inspectionSaveForm();const r=I.lookup(ops,e.dataset.id);if(r.driverId!==activeDriverId)throw new RangeError('Esta vistoria não pertence ao perfil selecionado.');inspectionSelectedId=r.id;inspectionStartNew=false;}else if(action==='inspection-new'){inspectionSaveForm();inspectionSelectedId=null;inspectionStartNew=true;}else if(action==='inspection-next'||action==='inspection-back'){const r=inspectionSaveForm();if(!r)throw new RangeError('Abra a vistoria para continuar.');const step=inspectionSteps.get(r.id)||1;if(action==='inspection-next')inspectionCheckStep(r,step);inspectionSteps.set(r.id,Math.max(1,Math.min(4,step+(action==='inspection-next'?1:-1))));}else if(action==='inspection-send'){const r=inspectionSaveForm();if(!r)throw new RangeError('Abra o rascunho antes de enviar.');inspectionCheckStep(r,4);I.submit(ops,r.id);inspectionSelectedId=r.id;toast('Vistoria enviada. A RODAVOLT vai conferir.');}else if(action==='inspection-examples'){const r=inspectionSaveForm()||I.lookup(ops,e.dataset.id);I.save(ops,r.id,{...r,items:{...r.items},evidence:I.slots.map(([slot])=>({slot,source:'illustrative'}))});for(const [slot]of I.slots){const key=r.id+':'+slot,url=inspectionPhotos.get(key);if(url)URL.revokeObjectURL(url);inspectionPhotos.delete(key);}}else return false;render();persist();if(['inspection-next','inspection-back','inspection-new','inspection-select','inspection-send'].includes(action))inspectionFocusStep();return true;}catch(error){inspectionError(error.message);return true;}}
 function inspectionSubmit(form,f){if(form.id==='inspection-work-form'){try{inspectionSaveForm();persist();toast('Rascunho salvo. Você pode continuar depois. As fotos ficam só nesta sessão.');}catch(error){inspectionError(error.message);}return true;}if(form.id==='inspection-create-form'){try{const d=driverProfile(),v=driverVehicle(),km=String(f.get('km')).trim()===''?NaN:Number(f.get('km')),chargePct=String(f.get('chargePct')).trim()===''?NaN:Number(f.get('chargePct'));if(!v)throw new RangeError('Peça à RODAVOLT para definir seu carro.');if(!Number.isInteger(km)||km<v.km)throw new RangeError('Informe os km do painel. O valor precisa ser igual ou maior que '+num(v.km)+' km.');if(!Number.isFinite(chargePct)||chargePct<0||chargePct>100)throw new RangeError('Informe a carga da bateria de 0 a 100%.');const r=I.create(ops,{driverId:d.id,vehicleId:v.id,type:String(f.get('type'))});I.save(ops,r.id,{...r,km,chargePct});inspectionSelectedId=r.id;inspectionStartNew=false;inspectionSteps.set(r.id,2);render();persist();inspectionFocusStep();}catch(error){inspectionError(error.message);}return true;}if(form.id==='inspection-review-form'){I.review(ops,String(f.get('entityId')),{action:String(f.get('action')),note:String(f.get('note'))});close();render();persist();toast('Parecer registrado na vistoria.');return true;}return false;}
 function inspectionPhotoChange(input){if(!input.dataset.inspectionPhoto)return;try{const r=inspectionSaveForm()||I.lookup(ops,input.dataset.inspectionId),file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>8*1024*1024)throw new RangeError('Escolha uma foto de até 8 MB.');const slot=input.dataset.inspectionPhoto,key=r.id+':'+slot,previous=inspectionPhotos.get(key);if(previous)URL.revokeObjectURL(previous);inspectionPhotos.set(key,URL.createObjectURL(file));I.save(ops,r.id,{...r,items:{...r.items},evidence:r.evidence.filter(e=>e.slot!==slot).concat({slot,source:'temporary'})});persist();render();}catch(error){inspectionError(error.message);}}
